def _validate_labels(labels):
    import re
    from collections import defaultdict

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__(self.messages)

    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')

    errors = defaultdict(list)

    for key, value in labels.items():
        key_str = str(key)
        value_str = str(value)

        if not isinstance(key, (str, int, bool)):
            errors[key_str].append(f'expected string or bytes-like object')
        elif not key_regex.match(key_str):
            errors[key_str].append(f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'")

        if not isinstance(value, (str, int, bool)):
            errors[value_str].append(f'expected string or bytes-like object')
        elif not value_regex.match(value_str):
            errors[value_str].append(f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9._-]+$'")

    if errors:
        formatted_errors = [{"'" + k + "'": v[0]} for k, v in errors.items()]
        raise ValidationError(formatted_errors)

