def absorb(self, args):
    result = []
    for i, expr in enumerate(args):
        if i + 1 < len(args):
            next_expr = args[i + 1]
            # Check for absorption A & (A | B) = A
            if expr == (expr & next_expr) | next_expr:
                result.append(expr)
                continue
            # Check for absorption A | (A & B) = A
            elif expr == (expr | next_expr) & next_expr:
                result.append(expr)
                continue
            # Check for negative absorption A & (~A | B) = A & B
            elif expr == (expr & (~expr | next_expr)):
                result.append(expr & next_expr)
                continue
            # Check for negative absorption A | (~A & B) = A | B
            elif expr == (expr | (~expr & next_expr)):
                result.append(expr | next_expr)
                continue
        result.append(expr)
    return result

