            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.isdigit():
        return int(size)
    else:
        factor = 1
        if size.endswith('K'):
            factor = 1000
        elif size.endswith('M'):
            factor = 1000 ** 2
        elif size.endswith('G'):
            factor = 1000 ** 3
        elif size.endswith('T'):
            factor = 1000 ** 4
        elif size.endswith('P'):
            factor = 1000 ** 5
        return int(size[:-1]) * factor

