    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide the interface {iface}")

    for name in iface.names():
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define the required method or attribute: {name}")
            continue

        required_method = getattr(iface, name)
        candidate_attr = getattr(candidate, name)

        if callable(required_method) and callable(candidate_attr):
            required_signature = inspect.signature(required_method)
            candidate_signature = inspect.signature(candidate_attr)
            try:
